from __future__ import annotations
import numpy as np
import math
import itertools
import types
FACTORS = ("edge", "oblique", "dim", "blur_noise", "low_contrast")

def _finite_upper_quantile(values: np.ndarray, q: float) -> float:
    x = np.asarray(values, dtype=float)
    if x.ndim != 1 or x.size == 0 or not np.all(np.isfinite(x)):
        raise RuntimeError("Phase 14 conformal score vector must be finite and nonempty")
    if not (0.0 < q < 1.0):
        raise RuntimeError("Phase 14 conformal quantile must be in (0,1)")
    x = np.sort(x)
    rank = min(x.size, int(math.ceil((x.size + 1) * q)))
    return float(x[rank - 1])

def _lagged(values: np.ndarray, lags: np.ndarray) -> np.ndarray:
    values = np.asarray(values, dtype=float)
    lags = np.asarray(lags, dtype=int)
    if len(values) != len(lags):
        raise RuntimeError("lag vector length mismatch")
    out = values.copy()
    finite = np.isfinite(values)
    for i, lag in enumerate(lags):
        j = max(0, i - max(0, int(lag)))
        while j > 0 and not finite[j]:
            j -= 1
        if finite[j]:
            out[i] = values[j]
    return out

def _all_subsets() -> tuple[frozenset[str], ...]:
    out: list[frozenset[str]] = []
    for size in range(len(FACTORS) + 1):
        for combo in itertools.combinations(FACTORS, size):
            out.append(frozenset(combo))
    return tuple(out)

def _subset_key(subset: frozenset[str]) -> str:
    if not subset:
        return "none"
    return "+".join(f for f in FACTORS if f in subset)

def _shapley_attenuation(advantages: dict[frozenset[str], float]) -> dict[str, object]:
    expected = set(_all_subsets())
    if set(advantages) != expected:
        raise RuntimeError("Phase 20 Shapley map requires exact 32-subset power set")
    n = len(FACTORS)
    factorial_n = math.factorial(n)
    contributions: dict[str, float] = {}
    for factor in FACTORS:
        phi = 0.0
        others = tuple(f for f in FACTORS if f != factor)
        for size in range(len(others) + 1):
            weight = math.factorial(size) * math.factorial(n - size - 1) / factorial_n
            for combo in itertools.combinations(others, size):
                s = frozenset(combo)
                with_factor = frozenset(set(s) | {factor})
                phi += weight * (float(advantages[s]) - float(advantages[with_factor]))
        contributions[factor] = float(phi)

    empty = frozenset()
    full = frozenset(FACTORS)
    attenuation = float(advantages[empty] - advantages[full])
    contribution_sum = float(sum(contributions.values()))
    return {
        "base_advantage": float(advantages[empty]),
        "full_advantage": float(advantages[full]),
        "endpoint_attenuation": attenuation,
        "contributions": contributions,
        "contribution_sum": contribution_sum,
        "efficiency_abs_error": float(abs(contribution_sum - attenuation)),
        "largest_attenuator": max(contributions, key=contributions.get),
        "largest_contribution": float(max(contributions.values())),
        "smallest_contributor": min(contributions, key=contributions.get),
        "smallest_contribution": float(min(contributions.values())),
    }

def _walsh_spectrum(advantages: dict[frozenset[str], float]) -> dict[str, object]:
    expected = set(p20._all_subsets())
    if set(advantages) != expected:
        raise RuntimeError("Phase 21 Walsh spectrum requires the exact 32-cell power set")

    coefficients: dict[frozenset[str], float] = {}
    for order in range(len(FACTORS) + 1):
        for combo in itertools.combinations(FACTORS, order):
            term = frozenset(combo)
            total = 0.0
            for cell, value in advantages.items():
                sign = 1.0
                for factor in term:
                    sign *= 1.0 if factor in cell else -1.0
                total += float(value) * sign
            coefficients[term] = float(total / len(expected))

    values = np.asarray([float(advantages[s]) for s in p20._all_subsets()], dtype=float)
    direct_variance = float(np.mean(np.square(values - float(np.mean(values)))))
    spectral_variance = float(sum(v * v for s, v in coefficients.items() if s))
    order_variance = {
        order: float(sum(v * v for s, v in coefficients.items() if len(s) == order))
        for order in range(1, len(FACTORS) + 1)
    }
    if not np.isfinite(spectral_variance) or spectral_variance <= 0.0:
        raise RuntimeError("Phase 21 requires finite positive centered surface variance")
    order_shares = {order: float(mass / spectral_variance) for order, mass in order_variance.items()}
    first_order = float(order_shares[1])

    def term_key(term: frozenset[str]) -> str:
        return p20._subset_key(term)

    return {
        "grand_mean": float(coefficients[frozenset()]),
        "coefficients": {term_key(s): float(coefficients[s]) for s in p20._all_subsets()},
        "first_order_coefficients": {factor: float(coefficients[frozenset({factor})]) for factor in FACTORS},
        "direct_centered_population_variance": direct_variance,
        "spectral_centered_variance": spectral_variance,
        "parseval_abs_error": float(abs(direct_variance - spectral_variance)),
        "order_variance_mass": {str(k): float(v) for k, v in order_variance.items()},
        "order_variance_share": {str(k): float(v) for k, v in order_shares.items()},
        "order_share_sum": float(sum(order_shares.values())),
        "first_order_variance_share": first_order,
        "interaction_variance_share": float(1.0 - first_order),
    }

def _model_from_spectrum(spectrum: dict[str, object]) -> dict[str, object]:
    return {
        "intercept": float(spectrum["grand_mean"]),
        "main_effects": {
            factor: float(spectrum["first_order_coefficients"][factor]) for factor in FACTORS
        },
    }

def _predict(model: dict[str, object], subset: frozenset[str]) -> float:
    value = float(model["intercept"])
    effects = model["main_effects"]
    for factor in FACTORS:
        value += float(effects[factor]) * (1.0 if factor in subset else -1.0)
    return float(value)

p20 = types.SimpleNamespace(_all_subsets=_all_subsets, _subset_key=_subset_key)

def _finite(values: np.ndarray | pd.Series | list[float]) -> np.ndarray:
    array = np.asarray(values, dtype=float)
    return array[np.isfinite(array)]

def _empirical_ks(a: np.ndarray, b: np.ndarray) -> float | None:
    a = np.sort(_finite(a))
    b = np.sort(_finite(b))
    if not len(a) or not len(b):
        return None
    points = np.sort(np.concatenate([a, b]))
    cdf_a = np.searchsorted(a, points, side="right") / len(a)
    cdf_b = np.searchsorted(b, points, side="right") / len(b)
    return float(np.max(np.abs(cdf_a - cdf_b)))

def _quantile_w1(a: np.ndarray, b: np.ndarray) -> float | None:
    a = _finite(a)
    b = _finite(b)
    if not len(a) or not len(b):
        return None
    quantiles = np.linspace(0.0, 1.0, 201)
    return float(np.mean(np.abs(np.quantile(a, quantiles) - np.quantile(b, quantiles))))

